mapper.select:
SELECT r.id AS id, r.item_id AS itemId, i.title AS itemTitle, i.cover_image AS itemCover, r.reporter_id AS reporterId, ru.nickname AS reporterNickname, r.reason AS reason, r.description AS description, r.status AS status, r.handle_action AS handleAction, r.handler_id AS handlerId, hu.nickname AS handlerNickname, r.handled_at AS handledAt, r.created_at AS createdAt FROM t_report r LEFT JOIN t_item i ON i.id = r.item_id LEFT JOIN t_user ru ON ru.id = r.reporter_id LEFT JOIN t_user hu ON hu.id = r.handler_id
AND r.status = #{q.status}
AND r.item_id = #{q.itemId}
ORDER BY r.created_at DESC, r.id DESC
